-- zlm-admin-parity-v3:down:start
UPDATE sys_menu SET redirect='',component='gb28181/zlm/workbench/MediaEntry',hide=false,updated_at=CURRENT_TIMESTAMP WHERE path='/media' AND deleted_at IS NULL;
UPDATE sys_menu SET component=CASE path WHEN '/media/overview' THEN 'gb28181/zlm/workbench/MediaOverview' WHEN '/media/monitoring' THEN 'gb28181/zlm/workbench/MediaMonitoring' WHEN '/media/ingress' THEN 'gb28181/zlm/workbench/IngressManagement' WHEN '/media/recordings' THEN 'gb28181/zlm/workbench/RecordingCenter' WHEN '/media/nodes' THEN 'gb28181/zlm/workbench/NodeManagement' WHEN '/media/scheduling' THEN 'gb28181/zlm/workbench/SchedulingManagement' ELSE 'gb28181/zlm/workbench/nodes/NodeDetail' END,hide=CASE WHEN path='/media/nodes/:id' THEN true ELSE false END,updated_at=CURRENT_TIMESTAMP WHERE path IN ('/media/overview','/media/monitoring','/media/ingress','/media/recordings','/media/nodes','/media/scheduling','/media/nodes/:id') AND deleted_at IS NULL;
UPDATE sys_menu SET component='gb28181/zlm/workbench/LegacyMediaRoute',hide=true,updated_at=CURRENT_TIMESTAMP WHERE path IN ('/gb28181/zlm/overview','/gb28181/zlm/nodes','/gb28181/zlm/runtime','/gb28181/zlm/streams','/gb28181/zlm/sessions','/gb28181/zlm/proxies','/gb28181/zlm/ffmpeg-sources','/gb28181/zlm/rtp-servers','/gb28181/zlm/config','/gb28181/zlm/scheduler','/gb28181/zlm/scheduler/logs','/gb28181/zlm/nodes/:id','/gb28181/cloud-recordings','/gb28181/recording-schedules') AND deleted_at IS NULL;
-- zlm-admin-parity-v3:down:end
